document.addEventListener('change',async e=>{
 try{
 if(e.target.dataset.accountKind){if(!e.target.value)return;try{const result=await api('connections/select',{id:e.target.value});generationTransport=result.kind;mcpQuote=null;mcpBalance=null;clearInterval(mcpPollTimer);await refresh(true);render();toast('Conta ativa: '+result.label);}catch(err){await refresh(true);render();throw err;}}
 if(e.target.id==='video-resolution'){videoResolution=e.target.value;mcpQuote=null;render();}
 if(e.target.id==='generation-transport'){generationTransport=e.target.value;mcpQuote=null;render();}
 if(e.target.id==='video-file')await setVideo(e.target.files[0]);
 if(e.target.id==='mcp-without-project'){mcpWithoutProject=e.target.checked;mcpQuote=null;}
 if(e.target.id==='prompt-toggle'){customPromptEnabled=e.target.checked;mcpQuote=null;$('#prompt').classList.toggle('hidden',!e.target.checked);$('#prompt-help').classList.toggle('hidden',e.target.checked);updateGenerationSummary();}
 if(e.target.dataset.compare){const id=e.target.dataset.compare;if(e.target.checked){if(compare.size>=2){e.target.checked=false;toast('Selecione dois vídeos.');return;}compare.add(id);}else compare.delete(id);render();}
 }catch(err){toast(err.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='prompt'){customPromptText=e.target.value;mcpQuote=null;updateGenerationSummary();}if(e.target.id==='search'){query=e.target.value;const start=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start);}});
document.addEventListener('dragover',e=>{if(e.target.closest('#drop'))e.preventDefault();});
document.addEventListener('drop',async e=>{if(e.target.closest('#drop')){e.preventDefault();try{await setVideo(e.dataTransfer.files[0]);}catch(err){toast(err.message);}}});
window.addEventListener('hashchange',()=>{query='';folder='';render();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){const b=app.querySelector('[data-action="generate"]');if(b&&!b.disabled)b.click();}});
modal.addEventListener('close',()=>{createBatch=null;render();});
async function loadAdmin(){adminLoading=true;try{adminData=await api('admin/dashboard');if(authInfo?.user?.admin&&location.hash==='#/admin')render();}catch(e){toast(e.message);}finally{adminLoading=false;}}
function loginScreen(){
 $('#connection').textContent='Higgsfield';$('#connection').title='Conexão Higgsfield';$('#connection').setAttribute('aria-label','Conexão Higgsfield');
 $('#admin-nav')?.remove();balanceData=null;drawBalance();
 $('#banner').textContent='';$('#banner').classList.add('hidden');
 const setup=authInfo?.setupRequired,register=registrationMode&&!setup;
 app.innerHTML='<div class="settings"><section><h1>'+(setup?'Configurar administrador':register?'Solicitar acesso':'Entrar')+'</h1><form id="'+(setup?'setup-form':register?'register-form':'login-form')+'" class="form">'+(setup?'<label for="setup-name">NOME</label><input id="setup-name" name="name" required><label for="setup-token">TOKEN DA INSTALAÇÃO</label><input id="setup-token" name="token" type="password" autocomplete="one-time-code" spellcheck="false" required><p class="muted">Use os 48 caracteres de /app/data/setup-token.txt no serviço fieldsia do EasyPanel. Não copie o comando nem o texto do terminal.</p>':'')+(register?'<label for="register-name">NOME</label><input id="register-name" name="name" autocomplete="name" maxlength="100" required>':'')+'<label for="login-email">EMAIL</label><input id="login-email" name="email" type="email" autocomplete="username" required><label for="login-password">SENHA</label><input id="login-password" name="password" type="password" autocomplete="'+(setup||register?'new-password':'current-password')+'" '+(setup||register?'minlength="12" maxlength="256"':'')+' required><div class="actions"><button class="primary" type="submit">'+(setup?'Configurar conta':register?'Solicitar aprovação':'Entrar')+'</button></div></form>'+(!setup?'<p class="muted">'+(register?'Seu cadastro ficará pendente até a aprovação do administrador.':'Cadastre-se e escolha um plano. O acesso será liberado conforme a confirmação de pagamento e as regras de aprovação.')+'</p><button data-action="registrationmode">'+(register?'Voltar ao login':'Solicitar acesso')+'</button>':'')+'</section></div>';
}
async function init(){try{authInfo=await api('auth/me');if(authInfo.user){await refresh(true);render();}else loginScreen();}catch(e){toast(e.message);}}
setInterval(async()=>{if(authInfo?.user)await refresh();},5000);
setInterval(refreshBalance,30000);window.addEventListener('focus',refreshBalance);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshBalance();});
init();

let installPrompt=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('#install-app').classList.remove('hidden');});
$('#install-app').addEventListener('click',async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#install-app').classList.add('hidden');});
window.addEventListener('appinstalled',()=>$('#install-app').classList.add('hidden'));
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});

window.addEventListener('message',event=>{
 if(event.source!==window||event.origin!==location.origin)return;
 if(event.data?.type==='FIELDS_IA_INSTAGRAM_CONNECTION'){instagramConnected=event.data.connected===true;const label=$('#instagram-connection-status');if(label)label.textContent=instagramConnectionLabel();}
 if(event.data?.type==='FIELDS_IA_INSTAGRAM_BUSY'){busy=true;toast('Importando vídeo com o Instagram conectado…');updateGenerationSummary();}
 if(event.data?.type==='FIELDS_IA_INSTAGRAM_IDLE'){busy=false;updateGenerationSummary();}
 if(event.data?.type==='FIELDS_IA_INSTAGRAM_ERROR')toast(String(event.data.message||'Falha ao importar. Tente novamente.'));
});
window.postMessage?.({type:'FIELDS_IA_INSTAGRAM_PROBE'},location.origin);
window.addEventListener('message',async event=>{if(event.source!==window||event.origin!==location.origin||event.data?.type!=='FIELDS_IA_INSTAGRAM_IMPORTED')return;const m=event.data.media;if(!m||!/^\/media\/[-_a-zA-Z0-9]+$/.test(m.url)||!Number.isFinite(m.duration))return;try{const check=await fetch(m.url,{method:'HEAD'});if(!check.ok)return;video={...m,name:'Vídeo Instagram importado'};mcpQuote=null;if(modal.open)modal.close();render();toast(m.trimmed?'Vídeo importado: primeiros 60 segundos, com áudio.':'Vídeo importado pela sua sessão Instagram.');}catch{toast('Vídeo salvo. Cole o link e clique em Baixar para abrir.');}});

if(typeof ResizeObserver!=='undefined'){new ResizeObserver(entries=>{const height=Math.ceil(entries[0].borderBoxSize?.[0]?.blockSize||document.querySelector('header').getBoundingClientRect().height);document.documentElement.style.setProperty('--app-header-height',height+'px');}).observe(document.querySelector('header'));}
